+/*
+ * Arq public site — "the drawing set".
+ *
+ * One aesthetic commitment carried all the way through: the site is composed
+ * like a precisely drafted architectural drawing set. Paper and ink, hairline
+ * rules, dimension ticks, mono annotations, sheet-number title blocks. The
+ * only colour is the brand's phthalo green (#0b6b50), used as drafting ink
+ * for links, focus and active marks — never as decoration for its own sake.
+ *
+ * Brand values come from design/tokens/brand.v4.css (black, white, phthalo
+ * green); the typefaces are the two families docs/design/DESIGN-SYSTEM.md
+ * names: Plus Jakarta Sans and JetBrains Mono, self-hosted (assets/fonts/).
+ * Dark mode is paper inverted to ink via prefers-color-scheme — no script,
+ * because the whole site works without JavaScript.
+ */
+
+@font-face {
+  font-family: 'Plus Jakarta Sans';
+  src: url('fonts/PlusJakartaSans-Variable.woff2') format('woff2');
+  font-weight: 200 800;
+  font-style: normal;
+  font-display: swap;
+}
+
+@font-face {
+  font-family: 'Plus Jakarta Sans';
+  src: url('fonts/PlusJakartaSans-Italic-Variable.woff2') format('woff2');
+  font-weight: 200 800;
+  font-style: italic;
+  font-display: swap;
+}
+
+@font-face {
+  font-family: 'JetBrains Mono';
+  src: url('fonts/JetBrainsMono-Variable.woff2') format('woff2');
+  font-weight: 100 800;
+  font-style: normal;
+  font-display: swap;
+}
+
+@font-face {
+  font-family: 'JetBrains Mono';
+  src: url('fonts/JetBrainsMono-Italic-Variable.woff2') format('woff2');
+  font-weight: 100 800;
+  font-style: italic;
+  font-display: swap;
+}
+
+:root {
+  /* Brand constants — see design/tokens/brand.v4.css. */
+  --arq-black: #000000;
+  --arq-white: #ffffff;
+  --arq-green: #0b6b50;
+
+  /* Paper-and-ink theme. */
+  --paper: var(--arq-white);
+  --ink: #101210;
+  --ink-muted: #565b57;
+  --hairline: #d8dcd9;
+  --hairline-strong: #101210;
+  --grid-line: rgba(11, 107, 80, 0.07);
+  --accent: var(--arq-green);
+  --accent-contrast: var(--arq-white);
+  --chip-built: #0b6b50;
+  --chip-neutral: #565b57;
+
+  --font-sans: 'Plus Jakarta Sans', 'Avenir Next', 'Segoe UI', sans-serif;
+  --font-mono: 'JetBrains Mono', 'SFMono-Regular', Consolas, monospace;
+
+  --measure: 68rem;
+  --space-1: 0.375rem;
+  --space-2: 0.75rem;
+  --space-3: 1.25rem;
+  --space-4: 2rem;
+  --space-5: 3.25rem;
+  --space-6: 5rem;
+
+  color-scheme: light dark;
+}
+
+@media (prefers-color-scheme: dark) {
+  :root {
+    --paper: #0c0e0d;
+    --ink: #f2f4f2;
+    --ink-muted: #a3aaa5;
+    --hairline: #262b28;
+    --hairline-strong: #f2f4f2;
+    --grid-line: rgba(38, 175, 137, 0.08);
+    --accent: #2ea582;
+    --accent-contrast: #0c0e0d;
+    --chip-built: #2ea582;
+    --chip-neutral: #a3aaa5;
+  }
+}
+
+* {
+  box-sizing: border-box;
+}
+
+html {
+  font-size: 100%;
+}
+
+body {
+  margin: 0;
+  background: var(--paper);
+  color: var(--ink);
+  font-family: var(--font-sans);
+  font-weight: 380;
+  line-height: 1.6;
+  -webkit-font-smoothing: antialiased;
+  text-rendering: optimizeLegibility;
+}
+
+.measure {
+  max-width: var(--measure);
+  margin-inline: auto;
+  padding-inline: clamp(1rem, 4vw, 2.5rem);
+}
+
+/* ------------------------------------------------------------------ */
+/* Links, buttons, focus                                               */
+/* ------------------------------------------------------------------ */
+
+a {
+  color: var(--accent);
+  text-decoration-thickness: 1px;
+  text-underline-offset: 0.2em;
+}
+
+a:hover {
+  text-decoration-thickness: 2px;
+}
+
+:focus-visible {
+  outline: 2px solid var(--accent);
+  outline-offset: 2px;
+}
+
+.skip-link {
+  position: absolute;
+  left: var(--space-2);
+  top: var(--space-2);
+  z-index: 10;
+  padding: var(--space-1) var(--space-2);
+  background: var(--paper);
+  border: 1px solid var(--hairline-strong);
