+}
+
+.nav-drawer summary::-webkit-details-marker {
+  display: none;
+}
+
+.nav-drawer[open] summary {
+  background: var(--ink);
+  color: var(--paper);
+  border-color: var(--ink);
+}
+
+.nav-drawer nav {
+  position: absolute;
+  right: clamp(1rem, 4vw, 2.5rem);
+  margin-top: var(--space-1);
+  display: flex;
+  flex-direction: column;
+  min-width: 12rem;
+  background: var(--paper);
