+}
+
+.note-body p {
+  color: var(--ink);
+}
+
+.note-body ul {
+  padding-left: 1.25rem;
+}
+
+.note-body li {
+  margin-block: 0.375rem;
+}
+
+/* ------------------------------------------------------------------ */
+/* Spec list (term/detail rows under a hairline each)                  */
+/* ------------------------------------------------------------------ */
+
+.spec-list {
+  margin: var(--space-3) 0 0;
+  border-top: 1px solid var(--hairline-strong);
